package com.learnagent.task; import jakarta.validation.constraints.NotBlank; import java.time.*; import java.util.*;
public final class TaskDtos { private TaskDtos(){} public record Request(UUID courseId,@NotBlank String title,String description,Instant dueAt,TaskStatus status,TaskPriority priority){} public record Response(UUID id,UUID courseId,String title,String description,Instant dueAt,TaskStatus status,TaskPriority priority,Instant createdAt,Instant updatedAt,Instant completedAt){static Response from(StudyTask t){return new Response(t.getId(),t.getCourseId(),t.getTitle(),t.getDescription(),t.getDueAt(),t.getStatus(),t.getPriority(),t.getCreatedAt(),t.getUpdatedAt(),t.getCompletedAt());}} }
